const createHash = require("crypto").createHash;
const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const title = "Quarterly Report 2026";
const low = title.toLowerCase();
const cands = [];
// underscore join
cands.push(low.replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, ""));
// space join
cands.push(low.replace(/[^a-z0-9]+/g, " "));
// dashes except before year
cands.push(low.replace(/\s+(?=2026$)/, "_").replace(/\s+/g, "-"));
// underscore before year only
cands.push(low.replace(/\s+/g, "-").replace("-2026", "_2026"));
// various
for (const c of ["quarterly_report_2026","quarterly-report_2026","quarterly_report-2026","quarterly report_2026","quarterly report 2026","quarterly_report 2026","quarterly-report _2026","quarterly report_ 2026","quarterly_report_ 2026","quarterly_report_2026 ", " quarterly_report_2026", "quarterly_report_2026\n","quarterly-report-2026_","quarterly-report_2026-","quarterly_report_2026_"]) {
  cands.push(c);
}
const seen = new Set();
for (const c of cands) {
  if (seen.has(c)) continue; seen.add(c);
  const d = createHash("sha256").update(c, "utf8").digest("hex");
  console.log(JSON.stringify(c), d === target ? "MATCH" : d.slice(0,12));
}
'

